css:
&.slide.tpl {
& { padding:0 100px 84px; display:flex; flex-direction:column; gap:0; }
.kb-band { position:relative; margin:0 -100px; height:330px; flex:none; overflow:hidden; }
.kb-band img { width:100%; height:100%; object-fit:cover; object-position:50% 30%; display:block; -webkit-mask-image:linear-gradient(to bottom,#000 35%,transparent); mask-image:linear-gradient(to bottom,#000 35%,transparent); opacity:.9; }
header { position:relative; margin-top:-96px; flex:none; }
header p { color:var(--accent); font:600 20px/1 var(--font-mono,var(--mono)); letter-spacing:.14em; text-transform:uppercase; margin:0 0 16px; }
header h2 { font-size:72px; line-height:1.04; margin:0; text-wrap:balance; }
header div { font-size:29px; line-height:1.36; color:var(--muted); margin-top:18px; max-width:76ch; }
header :empty { display:none; }
ol { flex:none; display:grid; grid-auto-flow:column; grid-auto-columns:minmax(0,1fr); gap:28px; list-style:none; padding:0; margin:48px 0 0; counter-reset:kb; align-items:stretch; }
li { counter-increment:kb; position:relative; display:flex; flex-direction:column; gap:18px; padding:38px 38px 40px; background:var(--surface); border:1px solid var(--line); border-radius:var(--radius); opacity:1!important; transform:none!important; transition:transform .35s ease,border-color .3s ease,opacity .3s ease,box-shadow .3s ease; }
li::before { content:counter(kb,decimal-leading-zero); font:600 22px/1 var(--font-mono,var(--mono)); color:var(--muted); }
li::after { content:""; position:absolute; left:34px; right:34px; top:0; height:4px; border-radius:0 0 4px 4px; background:var(--accent); transform:scaleX(0); transform-origin:left; transition:transform .4s ease; }
li b { font-size:40px; line-height:1.12; font-weight:650; color:var(--ink); }
li span { font-size:29px; line-height:1.42; color:var(--ink); opacity:0; transition:opacity .35s ease; }
li.in span,li:not([data-step]) span { opacity:1; }
li.step-current { border-color:color-mix(in srgb,var(--accent) 65%,transparent); box-shadow:0 24px 60px -28px color-mix(in srgb,var(--accent) 60%,transparent); transform:translateY(-8px)!important; }
li.step-current::after { transform:scaleX(1); }
li.step-current::before,li.step-current b { color:var(--accent); }
li.step-past { opacity:.6!important; }
&:has([data-template-end].in),&:has([data-template-end]:not([data-step])) { li { opacity:1!important; transform:none!important; box-shadow:none; border-color:var(--line); } li::after { transform:scaleX(1); } li::before { color:var(--accent); } li b { color:var(--ink); } li span { opacity:1; } }
[data-template-end] { position:absolute; width:0; height:0; overflow:hidden; }
&:has(.kb-band img[src=""]) { padding-top:100px; justify-content:center; padding-bottom:120px; } &:has(.kb-band img[src=""]) .kb-band { display:none; } &:has(.kb-band img[src=""]) header { margin-top:0; }
&:has(li:nth-child(4)) li { padding:28px 26px 24px; } &:has(li:nth-child(4)) li b { font-size:33px; } &:has(li:nth-child(4)) li span { font-size:25px; }
&[data-body-motion="none"] * { transition:none!important; }
@media(prefers-reduced-motion:reduce) { & * { transition:none!important; } }
}
